def maximumScore(a, b):
    # a: List[int] of length 4
    # b: List[int] of len(b) >= 4
    NEG = float('-inf')
    # dp[k]: best score after choosing k elements (for a[0..k-1]) from the prefix of b seen so far
    dp = [0, NEG, NEG, NEG, NEG]
    for x in b:
        # go backwards so each b[j] is used for at most one a[k]
        for k in range(4, 0, -1):
            if dp[k - 1] != NEG:
                cand = dp[k - 1] + a[k - 1] * x
                if cand > dp[k]:
                    dp[k] = cand
    return dp[4]
